ry_bulletin_2012_09_page_52.txt\njuly_2012 = {\n    'Gold stock': 11041,\n    'Special drawing rights': 54011,\n    'Foreign currencies': 50293,\n    'Reserve position in IMF': 34039\n}\n\n# July 2013 data from treasury_bulletin_2013_09_page_51.txt\njuly_2013 = {\n    'Gold stock': 11041,\n    'Special drawing rights': 54214,\n    'Foreign currencies': 47688,\n    'Reserve position in IMF': 34483\n}\n\n# Combine all 16 values\nall_values = (\n    list(july_2010.values()) + \n    list(july_2011.values()) + \n    list(july_2012.values()) + \n    list(july_2013.values())\n)\n\nprint(\"All 16 values:\")\nprint(all_values)\nprint()\n\n# Calculate geometric mean: (product of all values)^(1/16)\nlog_sum = sum(math.log(v) for v in all_values)\ngeometric_mean = math.exp(log_sum / 16)\n\nprint(f\"Geometric mean: {geometric_mean}\")\nprint(f\"Rounded to nearest hundredths: {round(geometric_mean, 2)}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
